<?php
class EstudianteModel {private PDO $pdo;function __construct(PDO $pdo){$this->pdo=$pdo;} function obtenerTodas(){return $this->pdo->query("SELECT e.*,u.nombre,u.apellido,u.correo,u.usuario,c.nombre_carrera FROM estudiantes e JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN carreras c ON c.id_carrera=e.id_carrera ORDER BY u.apellido,u.nombre")->fetchAll();} function obtenerPorId($id){$s=$this->pdo->prepare('SELECT e.*,u.nombre,u.apellido,u.correo,u.usuario FROM estudiantes e JOIN usuarios u ON u.id_usuario=e.id_usuario WHERE e.id_estudiante=?');$s->execute([$id]);return $s->fetch();} function obtenerPorUsuario($id){$s=$this->pdo->prepare('SELECT e.*,c.nombre_carrera FROM estudiantes e LEFT JOIN carreras c ON c.id_carrera=e.id_carrera WHERE e.id_usuario=?');$s->execute([$id]);return $s->fetch();}
 function crear($d){$this->pdo->beginTransaction();try{$u=$this->pdo->prepare('INSERT INTO usuarios(id_rol,nombre,apellido,correo,usuario,contrasena_hash,telefono) VALUES(3,?,?,?,?,?,?)');$u->execute([$d['nombre'],$d['apellido'],$d['correo'],$d['usuario'],password_hash($d['clave'],PASSWORD_DEFAULT),$d['telefono']??null]);$uid=$this->pdo->lastInsertId();$s=$this->pdo->prepare('INSERT INTO estudiantes(id_usuario,id_carrera,semestre,registro_universitario) VALUES(?,?,?,?)');$s->execute([$uid,$d['id_carrera'],$d['semestre'],$d['registro_universitario']]);$this->pdo->commit();return true;}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
 function editar($id,$d){$row=$this->obtenerPorId($id);$this->pdo->beginTransaction();try{$u=$this->pdo->prepare('UPDATE usuarios SET nombre=?,apellido=?,correo=?,usuario=?,telefono=? WHERE id_usuario=?');$u->execute([$d['nombre'],$d['apellido'],$d['correo'],$d['usuario'],$d['telefono']??null,$row['id_usuario']]);$s=$this->pdo->prepare('UPDATE estudiantes SET id_carrera=?,semestre=?,registro_universitario=? WHERE id_estudiante=?');$s->execute([$d['id_carrera'],$d['semestre'],$d['registro_universitario'],$id]);$this->pdo->commit();return true;}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
 function eliminar($id){$s=$this->pdo->prepare('SELECT id_usuario FROM estudiantes WHERE id_estudiante=?');$s->execute([$id]);$u=$s->fetchColumn();if(!$u)return false;$s=$this->pdo->prepare('DELETE FROM usuarios WHERE id_usuario=?');return $s->execute([$u]);}}
